<script lang="ts">
 import {onMount,onDestroy,createEventDispatcher,tick} from 'svelte';
 import {basicSetup,EditorView} from 'codemirror';
 import {EditorState,Compartment} from '@codemirror/state';
 import {javascript} from '@codemirror/lang-javascript';
 import {xml} from '@codemirror/lang-xml';
 import {json} from '@codemirror/lang-json';
 import type {CollaborationFactory,CollaborativeFileSession,CollaborativeState} from './collaborationTypes';
 import {EnterpriseFileClient,FileServiceError,languageForFile,isSaveShortcut,type EnterpriseFileRef} from './enterpriseFileClient';
 export let resource:EnterpriseFileRef;export let companyId:string;export let readOnly=false;
 export let accessSignal:AbortSignal|undefined=undefined;
 export let createCollaboration:CollaborationFactory|undefined=undefined;
 let collaboration:CollaborativeFileSession|null=null,collaborationState:CollaborativeState|null=null,stopCollaboration:(()=>void)|null=null;
 // Native session supplier; root may inject its existing account-bound adapter.
 export let tokenNow:()=>string=()=>localStorage.token||'';
 const dispatch=createEventDispatcher(),permissions=new Compartment(),syntax=new Compartment();
 let root:HTMLElement,mount:HTMLDivElement,view:EditorView|null=null,client:EnterpriseFileClient|null=null;
 let mounted=false,scope='',epoch=0,revision=0,title='',mime='',baseText='',draft='',loading=true,saving=false,conflict=false,denied=false,serverReadOnly=true,error='',notice='',refreshing=false;
 $: dirty=collaborationState?collaborationState.dirty:draft!==baseText;
 $: dispatch('dirty',{dirty});
 $: writable=!readOnly&&!serverReadOnly&&!denied&&(!collaborationState||!collaborationState.readOnly&&!collaborationState.conflict);
 $: if(view)view.dispatch({effects:permissions.reconfigure([EditorState.readOnly.of(!writable||loading),EditorView.editable.of(writable&&!loading)])});
 $: if(mounted&&scope!==JSON.stringify([companyId,resource?.scope,resource?.ownerId,resource?.kind,resource?.id])){scope=JSON.stringify([companyId,resource?.scope,resource?.ownerId,resource?.kind,resource?.id]);void open();}
 function language(name:string){const mode=languageForFile(name);return mode==='javascript'?javascript({typescript:/\.[cm]?tsx?$/i.test(name),jsx:/\.[jt]sx$/i.test(name)}):mode==='xml'?xml():mode==='json'?json():[];}
 function clearEditor(){view?.destroy();view=null;draft='';baseText='';revision=0;title='';mime='';}
 function closeCollaboration(){stopCollaboration?.();stopCollaboration=null;collaboration?.dispose();collaboration=null;collaborationState=null;}
 function revoked(message:string){epoch++;client?.dispose();client=null;clearEditor();closeCollaboration();loading=false;saving=false;conflict=false;denied=true;serverReadOnly=true;error=message;notice='';dispatch('revoked',{ref:resource});}
 function failure(cause:unknown){const e=cause as Error;if(e instanceof FileServiceError&&[401,403,404].includes(e.status)){revoked(e.message);return;}error=e.message||'File service unavailable.';if(e instanceof FileServiceError&&e.status===409)conflict=true;}
 function install(text:string){if(!view){view=new EditorView({parent:mount,state:EditorState.create({doc:text,extensions:[basicSetup,...(collaboration?[collaboration.extension]:[]),syntax.of(language(title)),permissions.of([EditorState.readOnly.of(!writable),EditorView.editable.of(writable)]),EditorView.contentAttributes.of({'aria-label':'File contents','spellcheck':'false'}),EditorView.updateListener.of(update=>{if(update.docChanged)draft=update.state.doc.toString();}),EditorView.theme({'&':{height:'100%',fontSize:'13px'},'.cm-scroller':{overflow:'auto',fontFamily:'ui-monospace, SFMono-Regular, Consolas, monospace'},'.cm-content':{minHeight:'260px'},'&.cm-focused':{outline:'none'}})]})});}else view.dispatch({changes:{from:0,to:view.state.doc.length,insert:text},effects:syntax.reconfigure(language(title))});draft=text;}
 async function open(){const n=++epoch;client?.dispose();client=null;clearEditor();closeCollaboration();loading=true;denied=false;conflict=false;error='';notice='';serverReadOnly=true;
  try{const current=new EnterpriseFileClient(resource,{companyIdNow:()=>companyId,tokenNow});client=current;const data=await current.load();if(n!==epoch)return;title=data.title;revision=data.revision;mime=data.mime;serverReadOnly=data.readOnly;baseText=data.text;draft=data.text;if(createCollaboration){const shared=await createCollaboration(resource,{companyIdNow:()=>companyId,tokenNow});if(n!==epoch){shared.dispose();return;}collaboration=shared;collaborationState=shared.state;stopCollaboration=shared.subscribe(state=>{if(n!==epoch)return;collaborationState=state;revision=state.revision;if(state.revoked)revoked('Collaboration access was revoked.');else if(state.conflict){conflict=true;error='The file epoch changed. Your local text is preserved for review.';}else if(state.error)error=state.error;});}loading=false;await tick();if(n!==epoch)return;install(collaboration?collaboration.text:data.text);if(!collaboration)current.watch(head=>{if(n!==epoch||head.revision===revision||saving)return;if(draft!==baseText){conflict=true;notice='A newer saved revision is available. Your unsaved text is preserved.';}else void remoteRefresh(n);},cause=>{if(n===epoch)failure(cause);});dispatch('loaded',{ref:resource,revision});}
  catch(cause){if(n===epoch){loading=false;failure(cause);}}
 }
 async function remoteRefresh(n:number){if(refreshing||!client)return;refreshing=true;try{const data=await client.load();if(n!==epoch)return;if(draft!==baseText){conflict=true;notice='The file changed while you were editing.';return;}title=data.title;revision=data.revision;mime=data.mime;serverReadOnly=data.readOnly;baseText=data.text;install(data.text);notice='Updated to the latest saved revision.';}catch(cause){if(n===epoch)failure(cause);}finally{refreshing=false;}}
 async function save(){if(!client||loading||saving||!writable||conflict||!dirty)return;const n=epoch,text=draft,head=revision;if(collaboration&&!collaborationState?.connected){error='Offline: updates are pending. Reconnect before checkpointing.';return;}saving=true;error='';notice='';try{const result=collaboration?await collaboration.checkpoint():await client.save(text,head,mime);if(n!==epoch)return;revision=result.revision;baseText=text;notice=collaboration?'Converged document checkpoint saved to company Drive.':draft===text?'Saved to company Drive.':'Saved. New edits are still unsaved.';dispatch('saved',{ref:resource,revision});}catch(cause){if(n===epoch)failure(cause);}finally{if(n===epoch)saving=false;}}
 function shortcut(event:KeyboardEvent){if(root?.contains(event.target as Node)&&isSaveShortcut(event)){event.preventDefault();event.stopPropagation();void save();}}
 function loadLatest(){if(draft!==baseText&&!confirm('Discard unsaved changes and load the latest saved revision?'))return;void open();}
 onMount(()=>{const accessRevoked=()=>revoked('Company access changed. Reopen this file.');accessSignal?.addEventListener('abort',accessRevoked,{once:true});if(accessSignal?.aborted){accessRevoked();return;}mounted=true;window.addEventListener('keydown',shortcut,true);const sessionChanged=(event:StorageEvent)=>{if(event.key==='token'||event.key===null)revoked('Your session changed. Reopen this file.');};window.addEventListener('storage',sessionChanged);return()=>{accessSignal?.removeEventListener('abort',accessRevoked);window.removeEventListener('keydown',shortcut,true);window.removeEventListener('storage',sessionChanged);};});
 onDestroy(()=>{epoch++;client?.dispose();clearEditor();closeCollaboration();});
</script>
<section bind:this={root} class="enterprise-file-editor" aria-label="Company code and text editor" aria-busy={loading||saving}>
 <header><div class="identity"><h2>{title||'Company file'}</h2><p>{revision?'Revision '+revision:'Opening authorized file'}{dirty?' · Unsaved changes':''}{!writable&&!loading?' · Read only':''}</p></div><button type="button" class="subtle" disabled={loading||saving||denied} on:click={loadLatest}>Load latest</button><button type="button" class="save" disabled={loading||saving||!writable||conflict||!dirty} on:click={save}>{saving?'Saving…':'Save'}<kbd>⌘ / Ctrl S</kbd></button></header>
 {#if loading}<p class="state" role="status">Loading the current authorized file revision…</p>{/if}
 {#if conflict}<p class="conflict" role="alert">This file changed elsewhere. Your unsaved text is kept; compare it with the latest version before saving. Automatic merging is unavailable.</p>{/if}
 {#if error}<p class="error" role="alert">{error}</p>{/if}
 <div bind:this={mount} class="code-surface" class:hidden={loading||denied}></div>
 <footer><span role="status" aria-live="polite">{notice||(!loading&&!denied?'UTF-8 · '+languageForFile(title).toUpperCase():'')}</span><span>{collaborationState?(collaborationState.connected?'Live coediting · '+collaborationState.peers+' connected':'Offline · edits queued'):'Revision sync · No live coediting'}</span></footer>
</section>
<style>
 .enterprise-file-editor{height:100%;min-height:360px;display:flex;flex-direction:column;color:inherit;background:var(--enterprise-surface,#fff);font-family:inherit}header{display:flex;align-items:center;gap:10px;padding:16px;border-bottom:1px solid var(--enterprise-border,#e5e7eb)}.identity{flex:1;min-width:0}h2{font-size:14px;font-weight:650;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin:0}p{margin:4px 0 0;font-size:12px;color:var(--enterprise-muted,#667085)}button{font:inherit;font-size:12px;border:1px solid var(--enterprise-border,#d0d5dd);border-radius:8px;padding:8px 10px;background:transparent;color:inherit;cursor:pointer}button:disabled{opacity:.45;cursor:default}button:focus-visible{outline:2px solid #6366f1;outline-offset:2px}.save{background:var(--enterprise-primary,#1d2939);color:var(--enterprise-on-primary,#fff);border-color:transparent}kbd{display:block;font:inherit;font-size:10px;opacity:.75;margin-top:2px}.code-surface{flex:1;min-height:260px;overflow:hidden}.hidden{display:none}.state,.error,.conflict{margin:0;padding:14px 16px;font-size:13px;line-height:1.5}.error{color:#b42318}.conflict{color:#93370d;background:#fffaeb;border-bottom:1px solid #fedf89}footer{display:flex;justify-content:space-between;gap:10px;padding:10px 16px;border-top:1px solid var(--enterprise-border,#e5e7eb);font-size:11px;color:var(--enterprise-muted,#667085)}
</style>
